function story(a){let has=saved.some(s=>s.url===a.url);return '<article class="story"><div><div><span class="tag">'+(a.critical?'PRIORITY · ':'')+esc(a.impact[0])+'</span><span class="meta">'+esc(a.source)+' · '+esc(when(a.date))+' IST</span></div><h3><a href="'+esc(a.url)+'" target="_blank" rel="noopener">'+esc(a.title)+' ↗</a></h3><p>'+esc(a.description)+'</p><div class="impact"><b>SECTOR LENS · '+esc(a.impact[1])+'</b><br>'+esc(a.impact[2])+'</div></div><button class="save" data-save="'+esc(a.url)+'" aria-label="'+(has?'Unsave':'Save')+' story">'+(has?'▣':'▢')+'</button></article>'}
function matches(a){return (!$('#search').value||a.title.toLowerCase().includes($('#search').value.toLowerCase()))}
function render(){let items=articles.filter(a=>Date.parse(a.date)<=Date.now()&&Date.now()-Date.parse(a.date)<=7*86400000&&(a.critical||(prefs.includes(a.impact[0])&&(topic==='All'||a.impact[0]===topic)))&&matches(a));$('#stories').innerHTML=items.map(story).join('')||'<div class="empty">No stories match this edition. Adjust your topics or search, or check source health.</div>';$('#count').textContent=items.length+' STORIES';$('#savedCount').textContent=saved.length||'';$('#savedStories').innerHTML=saved.filter(matches).map(story).join('')||'<div class="empty">A quieter place for your reading.<br>Use the square beside a headline to save it here.</div>';let names=$('#watchlist').value.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);$('#companyStories').innerHTML=articles.filter(a=>Date.now()-Date.parse(a.date)<=7*86400000&&matches(a)&&($('#companyUniverse').value==='all'||(niftyUniverse?.members||[]).some(m=>a.title.toLowerCase().includes(m.company.replace(/ Limited| Ltd.?/g,'').toLowerCase())||a.title.toUpperCase().split(/[^A-Z0-9-]+/).includes(m.symbol)))&&(names.length?names.some(n=>a.title.toLowerCase().includes(n)):a.impact[0]==='Earnings')).map(story).join('')||'<div class="empty">No matching company headlines in the current feeds.</div>';$('#filters').innerHTML=['All',...topics.filter(t=>prefs.includes(t))].map(t=>'<button class="chip '+(t===topic?'on':'')+'" data-topic="'+t+'">'+t+'</button>').join('');$('#prefchips').innerHTML=topics.map(t=>'<button class="chip '+(prefs.includes(t)?'on':'')+'" data-pref="'+t+'" aria-pressed="'+prefs.includes(t)+'">'+t+'</button>').join('')}
function horizon(e,days){let start=new Date(Date.now()+19800000).toISOString().slice(0,10);let end=new Date(Date.parse(start+'T00:00:00+05:30')+Number(days)*86400000).getTime();return new Date(Date.parse(e.date)+19800000).toISOString().slice(0,10)>=start&&Date.parse(e.date)<end}
function majorCompany(e){return /\b(HDFC|ICICI|SBI|Reliance|Infosys|TCS|Wipro|DLF|Bajaj|Tata|Hindustan|ITC|Larsen|Maruti|Nestle|Mahindra|Axis)\b/i.test(e.company)}
