function healthMarkup(list){return list.map(s=>'<div class="source"><span>'+esc(s.name)+(s.count!==undefined?' · '+s.count+' records':'')+'</span><span class="'+(s.ok&&!s.stale?'good':'bad')+'">'+(s.ok?(s.stale?'Cached · refresh failed':'Available'):'Unavailable')+(s.fetchedAt?' · retrieved '+esc(when(s.fetchedAt))+' IST':'')+(s.error?' · '+esc(s.error):'')+'</span></div>').join('')}
function eventCard(e){return '<div class="event"><div class="meta">'+esc(eventWhen(e))+' · '+esc(e.country||'INR')+'<span class="badge '+(e.impact==='High'?'high':'')+'">'+esc(e.impact||e.type)+'</span></div><h3>'+esc(e.company?e.company+' · '+e.type:eventTitle(e.title))+'</h3><div class="note">'+esc([...new Set((e.sources||[e.source]).map(x=>typeof x==='string'?x:x.name))].join(' + '))+(e.stale?' · Cached snapshot':'')+'</div></div>'}
function companyContext(e){return e.type==='Results'?'Compare revenue, margins, profit and management guidance with expectations. This is a scheduled results meeting, not a published earnings report.':e.type==='Dividend'?'Ex-date and record date determine entitlement. A dividend can cause a mechanical price adjustment.':'Read the official agenda and action details before inferring a market effect.'}
function tableDetails(e,id,company=false){let evidence=company?e.sources.map(s=>'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.name)+' ↗</a> · '+(s.stale?'Cached · ':'')+'checked '+esc(when(s.fetchedAt))+' IST').join('<br>'):'<a href="'+esc(e.url||e.sourceURL)+'" target="_blank" rel="noopener">Source ↗</a> · '+esc(e.sources.join(' + '))+(e.valueSource?' · Figures: '+esc(e.valueSource):'')+' · checked '+esc(when(e.fetchedAt))+' IST';return '<tr id="'+id+'" class="detail-row hidden"><td colspan="7"><div class="row-detail"><b>'+(company?'What to watch':esc(e.analysis[1]))+'</b><p>'+esc(company?companyContext(e):e.analysis[2])+'</p>'+(company?'<p>'+esc(e.description||e.title)+'</p>':e.scheduleNote?'<p>'+esc(e.scheduleNote)+'</p>':'')+'<div class="note">'+evidence+(e.stale?' · Last successful snapshot':'')+'</div></div></td></tr>'}
function tableButton(id){return '<button class="detail-button" data-expand="'+id+'" aria-expanded="false" aria-controls="'+id+'">Details</button>'}
function dateCell(e){return '<strong>'+esc(dateLabel(e.date))+'</strong>'+(e.dateOnly?'':'<span class="cell-sub">'+esc(new Date(e.date).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'}))+' IST</span>')}
function eventTitle(t){return t.replace(/\s*\(PLFS\)/g,'').replace(/\bRBI MPC policy/gi,'RBI monetary policy').replace(/\bCPI\b/g,'Consumer Price Index').replace(/\bGDP\b/g,'Gross Domestic Product').replace(/\bIIP\b/g,'Index of Industrial Production').replace(/\bMPC\b/g,'Monetary Policy Committee').replace(/\bPLFS\b/g,'Periodic Labour Force Survey').replace(/\bPMI\b/g,'Purchasing Managers’ Index').replace(/\bPPI\b/g,'Producer Price Index').replace(/\bYoY\b/g,'(year over year)').replace(/\bMoM\b/g,'(month over month)').replace(/\bQoQ\b/g,'(quarter over quarter)')}
